from pathlib import Path
from reportlab.lib.pagesizes import A4
from reportlab.lib.units import mm
from reportlab.pdfgen.canvas import Canvas
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.pdfbase import pdfmetrics
from textwrap import wrap

out=Path('output/pdf/koinonia-guia-aprendizaje-fases-0-13.pdf'); out.parent.mkdir(parents=True,exist_ok=True)
for n,p in [('D','C:/Windows/Fonts/DejaVuSans.ttf'),('DB','C:/Windows/Fonts/DejaVuSans-Bold.ttf'),('DM','C:/Windows/Fonts/DejaVuSansMono.ttf')]:
    if Path(p).exists(): pdfmetrics.registerFont(TTFont(n,p))
F='D' if 'D' in pdfmetrics.getRegisteredFontNames() else 'Helvetica'; B='DB' if 'DB' in pdfmetrics.getRegisteredFontNames() else 'Helvetica-Bold'; M='DM' if 'DM' in pdfmetrics.getRegisteredFontNames() else 'Courier'
sections=[
('Como usar esta guia','Las explicaciones se basan en el codigo local real. El Frontend es el mostrador, el Backend es la oficina que aplica reglas y MongoDB es el archivo. Rutas dirigen, controllers entienden HTTP, services aplican negocio y models describen documentos.'),
('Fase 0 - Funcionalidades','Implementado: servidor, MongoDB, registro, login, JWT, roles, comunidades, busqueda estructurada y geografica, guardados, descartes, perfil, frontend, administracion, eventos, comunidades vinculadas, primeras visitas y parte de experiencias. Parcial: recomendador externo, fuentes, multimedia, moderacion avanzada, adaptador Python y funciones de cuenta. Pendiente: interpretacion semantica, LLM, embeddings, RAG, indice vectorial, comparacion, contacto con consentimiento, refresh tokens, verificacion de correo, migracion y escalabilidad.'),
('Fase 1 - Estructura','Backend/src contiene server.js, app.js, config, routes, controllers, services, models, middleware, validation y utils. Backend/test contiene pruebas; Backend/docs contratos; scripts operaciones. Frontend/src contiene React; Frontend/test recorridos; docs diseno y diagramas. Flujo: Frontend -> HTTP -> Express -> route -> middleware -> controller -> service -> model/Mongoose -> MongoDB.'),
('Fase 2 - Arranque, app.js, MongoDB y .env','server.js ejecuta loadConfig(), await connectDB(config.mongoUri), createApp(config).listen(config.port), registra SIGINT/SIGTERM y captura errores de inicio. app.js configura Express, Helmet, CORS, JSON, /health, /api y errores. db.js hace mongoose.connect y model.init. Variables: MONGO_URI conexion; JWT_SECRET firma JWT; PORT puerto; CORS_ORIGINS frontend; ENABLE_TEST_UI pruebas; RECOMMENDER_URL/TOKEN servicio externo; CLOUDINARY para imagenes; TRUST_PROXY_HOPS proxies; RESEND_API_KEY, MAIL_FROM y APP_PUBLIC_URL correo; NODE_ENV entorno.'),
('Fase 3 - async, await y flujo de una función','En Koinonía una función como church.service.search es async porque necesita esperar consultas a MongoDB. Una Promise representa un resultado que todavía no llegó: como pedir un expediente al archivo y recibir un comprobante de que lo están buscando. await espera ese resultado sin bloquear todo el servidor. Entrada: query ya validada y usuario si corresponde. Proceso: construir filtros, consultar Church.find y countDocuments, ordenar y transformar con publicChurch. Salida: un objeto con data y pagination. return entrega esa salida al controller. throw abandona la función con un error para que errorHandler responda. next, en un middleware, entrega el control al siguiente middleware; no reemplaza return ni throw. Si ocurre un error dentro de try, catch puede hacer throw err o next(err).'),
('Fase 4 - HTTP y login','GET /api/churches: app.js monta /api, api.routes dirige a church.list, Zod valida req.query, church.service.search consulta Church/MongoDB, publicChurch filtra y res.json responde. POST /api/auth/login: main.jsx envia email y password; auth.controller valida, busca User con password y sessionVersion, bcrypt compara, comprueba active, crea JWT HS256 con subject, expiracion 1h, issuer y audience, y devuelve token y publicUser. req.params es parte de URL; req.query son opciones tras ?; req.body es JSON de POST/PUT/PATCH.'),
('Fase 5 - church.controller.js','Funciones: list, get, mine, detail, leaderIdentifiers, create, update, status, representatives, remove, restore, eligibleRepresentatives, createRepresentative, requestPublication y checklist. Controller debe leer HTTP, validar, llamar services y responder. En el codigo actual varias persistencias aun viven en controller: Church.create, church.save y consultas de User. Respuestas principales: list/get/mine/detail/update/status/representatives/restore/checklist 200; create/createRepresentative 201; remove 204; errores 400, 401, 403, 404, 409 o 500 segun la rama.'),
('Fase 6 - Services y recomendador','recommendation.service.js exporta rank, satisfies y enrich. rank recibe comunidad, preferencias y modos; calcula coincidencias, componentes, evidencia y score. satisfies devuelve booleano. enrich lee fuentes aprobadas y llama opcionalmente al recomendador externo, validando candidatos y fuentes. Pesos actuales: doctrina 40%, distancia 25%, actividades 20%, disponibilidad 10%, calidad 5%. No interpreta aun query libre ni usa embeddings o RAG. church.service.js contiene visible, publicChurch, managed, checkVersion, filters, search y exact. Estos services consultan o calculan, pero no guardan comunidades.'),
('Fase 7 - church.model.js','Church representa la coleccion churches. Incluye identification, verification, location, christianIdentity, doctrine, meetings, community, leadership, contact, firstVisit, media, metadata, referencias y active. Embebidos: location, meetings, leadership, media y metadata. ObjectId: representatives, createdBy, updatedBy, requestedBy y mergedInto. Indices: location.coordinates 2dsphere para GeoNear; active + dataStatus + commune para consultas publicas; denomination para filtros; provider + placeId unico parcial para duplicados externos. Ubicacion GeoJSON: type Point y coordinates [longitud, latitud].'),
('Fase 8 - Validacion','Zod valida solicitudes HTTP: body, query, params, tipos, formatos, longitudes, enum, reglas entre campos, conversion de query strings y campos desconocidos con z.strictObject. Mongoose valida antes de persistir: required, tipos, enum, defaults, rangos, validaciones personalizadas, indices unicos, referencias y strict: throw. Campo desconocido: Zod lo rechaza primero con 400 VALIDATION_ERROR; si llega a Mongoose, StrictModeError se convierte en 400 por errorHandler.'),
('Fase 9 - Autenticacion y autorizacion','auth pregunta quien eres: lee Bearer, verifica JWT, busca User, comprueba active y sessionVersion y asigna req.user. roles verifica rol. svc.managed verifica el recurso: admin puede administrar; representative solo si su id esta en church.representatives. No basta con login ni rol: tambien debe existir asignacion concreta.'),
('Fase 10 - Ciclo de vida','draft es preparacion; published es publico; verified es verificado por admin. Edicion de verified vuelve a published. Desactivar pone active=false, conserva el documento y responde 204; restore pone active=true y draft. publicChurch oculta publicationRequest, representatives, createdBy, updatedBy, __v, importInfo, reviewImport, privateFields y filtra doctrina, contacto, externalProfile, accesibilidad y comunidad segun privacidad. If-Match compara la version leida con metadata.version: ausente es opcional; formato incorrecto 400; version antigua 409 STALE_VERSION; coincidencia permite guardar e incrementar version.'),
('Fase 11 - Busqueda y ranking','/churches/search valida q, commune, denomination, branch, doctrine, activity, language, day, lat, lng, radius, sort, page y limit. filters parte de active=true y published/verified, combina filtros con AND y usa nombre parcial o coincidencias exactas. Busqueda cercana: GeoJSON + indice 2dsphere + $geoNear; recibe [lng,lat], calcula distanceMeters y aplica radio en metros. Modos: required filtra y puntua; preferred solo puntua; disabled ignora. Los descartes se excluyen. Query libre aun no se interpreta.'),
('Fase 13 - React y api.js','index.html contiene root y carga main.jsx. main.jsx ejecuta createRoot(...).render(<App />), controla route, token, user, borradores y selecciona pantallas por location.hash. api.js centraliza fetch, base /api o VITE_API_BASE_URL, JSON, Authorization Bearer, timeout, errores HTTP y sessionStorage. Recorrido Explore: form cambia -> search copia form a query -> useEffect construye /api/churches/search -> api.js fetch -> Express -> route -> controller -> Zod -> service -> Church.find/countDocuments -> MongoDB -> publicChurch -> JSON -> setResult -> tarjetas React.'),
('Glosario final','Express: servidor HTTP. Mongoose: modelos y consultas MongoDB. Controller: HTTP y respuestas. Service: reglas y operaciones. Model: documentos e indices. Middleware: procesamiento previo. JWT: token firmado. Zod: contrato de entrada. GeoJSON Point: punto [longitud, latitud]. ETag/If-Match: versionado. RAG: recuperacion documental, pendiente. Promise: resultado futuro. async/await: espera legible de Promises.')]

sections += [
('Fase 2 - server.js línea por línea','const loadConfig importa la lectura y validación de .env. connectDB y disconnectDB abren y cierran Mongoose. createApp construye Express. start es async porque debe esperar MongoDB. config=loadConfig obtiene la configuración. await connectDB impide recibir solicitudes antes de conectar la base. createApp(config).listen abre el puerto y conserva el objeto server. shutdown cierra primero HTTP y luego MongoDB. process.once registra Ctrl+C y SIGTERM. start().catch captura errores de configuración, conexión o arranque y termina con código 1. La diferencia esencial es: server.js enciende, escucha y apaga; app.js decide cómo responde la aplicación.'),
('Fase 2 - conexión MongoDB','db.js importa mongoose. La lista models carga User, Church, Interaction, Source, LinkedCommunity, Event y EventParticipation. mongoose.connect(uri,{serverSelectionTimeoutMS:10000}) intenta encontrar MongoDB durante diez segundos. Promise.all(models.map(model=>model.init())) inicializa índices y esquemas. MONGO_URI puede apuntar a MongoDB local, Docker o Atlas. MongoDB no recibe consultas desde server.js: server.js abre la conexión; después controllers y services usan los modelos.'),
('Fase 4 - GET /api/churches detallado','app.use(/api, api.routes) combina el prefijo /api con router.get(/churches, church.list). El controller valida req.query con v.search y llama svc.search(query). church.service.filters parte de active:true y metadata.dataStatus en published/verified. Los filtros commune, denomination, branch, doctrine, activity, language y day se traducen a rutas del documento. q usa nombre parcial; los demás filtros usan expresiones exactas sin distinguir mayúsculas. Sin coordenadas se ejecutan Church.find y Church.countDocuments en paralelo. El resultado pasa por publicChurch y vuelve como data más pagination.'),
('Fase 4 - login completo','main.jsx ejecuta api(/auth/login,{method:POST,body:{email,password}}). api.js serializa JSON y añade Content-Type. Express.json coloca el contenido en req.body. auth.controller valida v.login. User.findOne busca email y select solicita password y sessionVersion, que normalmente están ocultos. bcrypt.compare compara la contraseña con el hash. Si no existe, está inactivo o la contraseña falla, responde 401 con mensaje uniforme. jwt.sign firma sv, subject, duración, issuer y audience. El frontend recibe el token y lo envía después como Authorization: Bearer token.'),
('Fase 5 - controller versus service','Controller es la capa de transporte: entiende HTTP, extrae parámetros y produce status y JSON. Service es la capa de negocio: conoce publicación, asignación, visibilidad, filtros, versiones y reglas del dominio. En Koinonía la separación es mixta. search, publicChurch, managed y filters están en church.service. Pero create, update, status, representatives, remove y restore todavía ejecutan Church.create o church.save en el controller. No significa que fallen; significa que su responsabilidad está más mezclada y podría refactorizarse.'),
('Fase 6 - rank paso a paso','criterionPaths relaciona una preferencia con el campo real de Church. overlap calcula coincidencias entre wanted y actual. rank ignora criterios ausentes o disabled; lee valores; calcula ratio; registra matched, partial, not_matched o unknown; calcula radiusKm si existe distanceMeters; agrupa scores en doctrine, distance, activities y availability; obtiene quality; normaliza los pesos activos; devuelve score, components, criteria, evidence, church, explanation y sourceIds. enrich solo añade explicaciones y fuentes aprobadas del servicio externo y rechaza candidatos o fuentes no autorizadas.'),
('Fase 7 - documento Church','identification guarda nombre y descripción. verification guarda declaración y fecha. location guarda dirección, comuna y Point. christianIdentity y doctrine guardan identidad y doctrina. meetings contiene horarios embebidos. community guarda actividades, ministerios y grupos. leadership guarda líderes institucionales embebidos. contact guarda canales. firstVisit guarda configuración, mientras las visitas concretas usan visit.model. metadata guarda dataStatus y version. representatives, createdBy y updatedBy son referencias User. active permite baja lógica. Un documento embebido vive dentro de Church; un ObjectId apunta a otra colección.'),
('Fase 8 - campo no permitido','Los esquemas Zod son strictObject. Si el cliente manda identification.secretAdminFlag, v.parse(v.church,req.body) genera HttpError 400 antes de Church.create. Si un código interno evita Zod, el esquema Church tiene strict:throw y Mongoose produce StrictModeError. errorHandler reconoce StrictModeError, ValidationError y CastError y los traduce a 400 VALIDATION_ERROR. Esta doble barrera evita que el cliente escriba campos técnicos como createdBy, active, representatives o metadata.'),
('Fase 9 - representante y comunidad','La ruta PUT /churches/:id tiene auth y managers antes de church.update. auth verifica JWT y coloca req.user. managers permite representative o admin. Luego svc.managed consulta la comunidad y comprueba que admin pueda entrar o que representative exista en church.representatives. Si no, lanza 403 FORBIDDEN. La autorización no es solo el rol: es rol más recurso concreto. Después checkVersion protege la edición y solo entonces se valida y guarda el body.'),
('Fase 10 - estados y privacidad','Al crear, dataStatus empieza en draft. publication-request guarda una solicitud pending y no publica automáticamente. status exige checklist para published o verified. Solo admin puede verificar y la primera publicación registra firstPublishedByAdminAt. Editar verified devuelve published. remove solo pone active=false; restore reactiva y devuelve a draft. publicChurch trabaja sobre toObject para no modificar el documento, elimina trazabilidad y filtra email, phone, soteriology, eschatology, accesibilidad, enlaces mailto/tel, estilos y banderas privadas.'),
('Fase 11 - recomendación actual','El controller recommendation.recommend mezcla preferencias guardadas y enviadas, modos y ubicación. required crea filtros MongoDB antes de obtener candidatos. Los descartados se consultan desde Interaction y se excluyen. Cada candidato pasa a rank. ranked se ordena por score descendente y churchId como desempate. Si no hay RECOMMENDER_URL, mode es deterministic. Si existe, enrich puede llamar al adaptador externo, pero no puede cambiar filtros, IDs ni puntuaciones. La consulta libre genera advertencia porque queryInterpreted es false.'),
('Fase 13 - recorrido Explore','Explore mantiene form y query separados. El usuario edita form; al enviar search hace preventDefault, reinicia page y copia form a query. El useEffect construye URLSearchParams con page, limit y filtros. Si hay ubicación, envía lat, lng y radius. api.js ejecuta fetch y procesa errores. La respuesta llega a setResult. React vuelve a renderizar result.data.map(Card). La tarjeta muestra nombre, denominación, dirección, distancia, reunión, actividades y estado. request.current impide que una respuesta vieja reemplace una búsqueda nueva.')]

from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak
from xml.sax.saxutils import escape

styles=getSampleStyleSheet()
title_style=ParagraphStyle('TitleK',parent=styles['Title'],fontName=B,fontSize=24,leading=30,textColor=colors.HexColor('#062034'),spaceAfter=12)
subtitle_style=ParagraphStyle('SubK',parent=styles['Normal'],fontName=F,fontSize=11,leading=16,textColor=colors.HexColor('#3f5965'),spaceAfter=18)
section_style=ParagraphStyle('SectionK',parent=styles['Heading1'],fontName=B,fontSize=15,leading=20,textColor=colors.HexColor('#062034'),spaceBefore=14,spaceAfter=7,keepWithNext=True)
body_style=ParagraphStyle('BodyK',parent=styles['BodyText'],fontName=F,fontSize=9.5,leading=14,textColor=colors.HexColor('#17252d'),spaceAfter=8,alignment=4)
note_style=ParagraphStyle('NoteK',parent=body_style,fontSize=8.5,leading=12,textColor=colors.HexColor('#48616b'),leftIndent=8,rightIndent=8,backColor=colors.HexColor('#eef5f5'),borderPadding=7,spaceBefore=5,spaceAfter=10)

def footer(canvas,doc):
    canvas.saveState(); width,height=A4
    canvas.setStrokeColor(colors.HexColor('#bfcacc')); canvas.line(18*mm,13*mm,width-18*mm,13*mm)
    canvas.setFillColor(colors.HexColor('#53666d')); canvas.setFont(F,7)
    canvas.drawString(18*mm,8*mm,'Koinonia - Guia de aprendizaje')
    canvas.drawRightString(width-18*mm,8*mm,'Pagina %d'%doc.page); canvas.restoreState()

doc=SimpleDocTemplate(str(out),pagesize=A4,rightMargin=18*mm,leftMargin=18*mm,topMargin=18*mm,bottomMargin=20*mm,title='Koinonia - Guia de aprendizaje')
story=[Spacer(1,18*mm),Paragraph('Koinonia: guía completa de aprendizaje',title_style),Paragraph('Compilación ampliada de las fases 0 a 13, basada en el código local real del proyecto.',subtitle_style),Paragraph('<b>Cómo leerla:</b> cada sección responde qué entra, qué proceso ocurre, qué sale y cómo se conecta con la siguiente capa. El mostrador es React, la oficina es Express y MongoDB es el archivo donde se guardan los documentos.',note_style),PageBreak()]
for index,(title,text) in enumerate(sections):
    if index==0: story.append(Paragraph('Índice y mapa de lectura',section_style))
    story.append(Paragraph(escape(title),section_style))
    story.append(Paragraph(escape(text),body_style))
    if title.startswith('Fase ') and ('server.js' in title or 'login completo' in title or 'controller versus' in title or 'rank paso' in title or 'documento Church' in title or 'campo no permitido' in title or 'representante y comunidad' in title or 'estados y privacidad' in title or 'recomendación actual' in title or 'recorrido Explore' in title):
        story.append(Paragraph('Idea clave: sigue siempre el hilo entrada → validación → autorización → lógica de negocio → persistencia → respuesta/error.',note_style))
doc.build(story,onFirstPage=footer,onLaterPages=footer)
print(out)
